189	#[derive(Debug, PartialEq, Eq, Clone)]
190	enum ParseState<'a> {
191	    /// Parsing a value done, there is no state to record.
192	    ValueDone,
193	
194	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
195	    Pos((usize, usize)),
196	
197	    /// Parsing a optional flag argument
198	    Opt((&'a clap::Arg, usize)),
199	}
