201	fn complete_arg(
202	    arg: &clap_lex::ParsedArg<'_>,
203	    cmd: &clap::Command,
204	    current_dir: Option<&std::path::Path>,
205	    pos_index: usize,
206	    is_escaped: bool,
207	    state: ParseState<'_>,
208	    used_args: &[clap::Id],
209	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
210	    debug!(
211	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
212	        arg,
213	        cmd.get_name(),
214	        current_dir,
215	        pos_index,
216	        state
217	    );
218	    let mut completions = Vec::<CompletionCandidate>::new();
219	
220	    match state {
221	        ParseState::ValueDone => {
222	            if !is_escaped {
223	                if let Ok(value) = arg.to_value() {
224	                    completions.extend(complete_subcommand(value, cmd));
225	                }
226	            }
227	
228	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
229	                completions.extend(complete_arg_value(
230	                    arg.to_value(),
231	                    positional,
232	                    current_dir,
233	                    0,
234	                ));
235	            }
236	            if !is_escaped {
237	                completions.extend(complete_option(arg, cmd, current_dir));
238	            }
239	        }
240	        ParseState::Pos((_, num_arg)) => {
241	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
242	                completions.extend(complete_arg_value(
243	                    arg.to_value(),
244	                    positional,
245	                    current_dir,
246	                    num_arg.saturating_sub(1),
247	                ));
248	                if !is_escaped
249	                    && positional
250	                        .get_num_args()
251	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
252	                {
253	                    completions.extend(complete_option(arg, cmd, current_dir));
254	                }
255	            }
256	        }
257	        ParseState::Opt((opt, count)) => {
258	            completions.extend(complete_arg_value(
259	                arg.to_value(),
260	                opt,
261	                current_dir,
262	                count.saturating_sub(1),
263	            ));
264	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
265	            if count > min && can_switch_to_other_arg(opt, arg) {
266	                // The option's required values are satisfied and this word
267	                // would be parsed as a new flag rather than another value, so
268	                // also complete it as a positional, flag, option or subcommand.
269	                completions.extend(complete_arg(
270	                    arg,
271	                    cmd,
272	                    current_dir,
273	                    pos_index,
274	                    is_escaped,
275	                    ParseState::ValueDone,
276	                    used_args,
277	                )?);
278	            }
279	        }
280	    }
281	    filter_unavailable_args(&mut completions, cmd, used_args);
282	    if completions.iter().any(|a| !a.is_hide_set()) {
283	        completions.retain(|a| !a.is_hide_set());
284	    }
285	    dedup_argument_candidates(&mut completions, arg.is_empty());
286	
287	    let mut tags = Vec::new();
288	    for candidate in &completions {
289	        let tag = candidate.get_tag().cloned();
290	        if !tags.contains(&tag) {
291	            tags.push(tag);
292	        }
293	    }
294	    completions.sort_by_key(|c| {
295	        (
296	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
297	            c.get_display_order(),
298	        )
299	    });
300	
301	    Ok(completions)
302	}
