404	fn complete_arg_value(
405	    value: Result<&str, &OsStr>,
406	    arg: &clap::Arg,
407	    current_dir: Option<&std::path::Path>,
408	    arg_index: usize,
409	) -> Vec<CompletionCandidate> {
410	    let mut values = Vec::new();
411	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
412	
413	    let (prefix, value) =
414	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
415	
416	    let value_os = match value {
417	        Ok(value) => OsStr::new(value),
418	        Err(value_os) => value_os,
419	    };
420	
421	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
422	        values.extend(completer.complete_at(arg_index, value_os));
423	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
424	        values.extend(complete_value_candidates(
425	            value_os,
426	            completer.value_candidates(),
427	        ));
428	    } else if let Some(possible_values) = possible_values(arg) {
429	        if let Ok(value) = value {
430	            values.extend(complete_candidates_str(
431	                value,
432	                possible_value_candidates(possible_values),
433	            ));
434	        }
435	    } else {
436	        match arg.get_value_hint() {
437	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
438	                // Should not complete
439	            }
440	            clap::ValueHint::AnyPath => {
441	                values.extend(complete_path(value_os, current_dir, &|_| true));
442	            }
443	            clap::ValueHint::FilePath => {
444	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
445	            }
446	            clap::ValueHint::DirPath => {
447	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
448	            }
449	            clap::ValueHint::ExecutablePath => {
450	                use is_executable::IsExecutable;
451	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
452	            }
453	            clap::ValueHint::CommandName
454	            | clap::ValueHint::CommandString
455	            | clap::ValueHint::CommandWithArguments
456	            | clap::ValueHint::Username
457	            | clap::ValueHint::Hostname
458	            | clap::ValueHint::Url
459	            | clap::ValueHint::EmailAddress => {
460	                // No completion implementation
461	            }
462	            _ => {
463	                // Safe-ish fallback
464	                values.extend(complete_path(value_os, current_dir, &|_| true));
465	            }
466	        }
467	
468	        values.sort();
469	    }
470	
471	    if let Some(prefix) = prefix {
472	        values = values
473	            .into_iter()
474	            .map(|comp| comp.add_prefix(prefix))
475	            .collect();
476	    }
477	    values = values
478	        .into_iter()
479	        .map(|comp| {
480	            if comp.get_tag().is_some() {
481	                comp
482	            } else {
483	                comp.tag(Some(arg.to_string().into()))
484	            }
485	        })
486	        .collect();
487	
488	    debug!("complete_arg_value: values={values:?}");
489	    values
490	}
491	
492	fn rsplit_delimiter<'s, 'o>(
493	    value: Result<&'s str, &'o OsStr>,
494	    delimiter: Option<char>,
495	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
496	    let delimiter = delimiter?;
497	    let value = value.ok()?;
498	    let pos = value.rfind(delimiter)?;
499	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
500	    Some((Some(prefix), Ok(value)))
501	}
