558	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
559	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
560	fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
561	    debug!("longs: name={}", p.get_name());
562	
563	    p.get_arguments()
564	        .filter_map(|a| {
565	            a.get_long_and_visible_aliases().map(|longs| {
566	                longs
567	                    .into_iter()
568	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
569	            })
570	        })
571	        .flatten()
572	        .collect()
573	}
574	
575	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
576	fn hidden_longs_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
577	    debug!("longs: name={}", p.get_name());
578	
579	    p.get_arguments()
580	        .filter_map(|a| {
581	            a.get_aliases().map(|longs| {
582	                longs.into_iter().map(|s| {
583	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
584	                })
585	            })
586	        })
587	        .flatten()
588	        .collect()
589	}
