591	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
592	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
593	fn shorts_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
594	    debug!("shorts: name={}", p.get_name());
595	
596	    p.get_arguments()
597	        .filter_map(|a| {
598	            a.get_short_and_visible_aliases().map(|shorts| {
599	                shorts.into_iter().map(|s| {
600	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
601	                        a.get_help()
602	                            .cloned()
603	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
604	                    )
605	                })
606	            })
607	        })
608	        .flatten()
609	        .collect()
610	}
611	
612	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
613	    candidate
614	        .help(arg.get_help().cloned())
615	        .id(Some(format!("arg::{}", arg.get_id())))
616	        .tag(Some(
617	            arg.get_help_heading()
618	                .unwrap_or("Options")
619	                .to_owned()
620	                .into(),
621	        ))
622	        .display_order(Some(arg.get_display_order()))
623	        .hide(arg.is_hide_set())
624	}
625	
626	/// Get the possible values for completion
627	fn possible_values(
628	    a: &clap::Arg,
629	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
630	    if !a.get_num_args().expect("built").takes_values() {
631	        None
632	    } else {
633	        a.get_value_parser().possible_values()
634	    }
635	}
636	
637	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
638	///
639	/// Subcommand `rustup toolchain install` would be converted to
640	/// `("install", "rustup toolchain install")`.
641	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
642	    debug!("subcommands: name={}", p.get_name());
643	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
644	    p.get_subcommands()
645	        .flat_map(|sc| {
646	            sc.get_name_and_visible_aliases()
647	                .into_iter()
648	                .map(|s| populate_command_candidate(s, p, sc))
649	                .chain(
650	                    sc.get_aliases()
651	                        .map(|s| populate_command_candidate(s, p, sc).hide(true)),
652	                )
653	        })
654	        .collect()
655	}
656	
657	fn populate_command_candidate(
658	    candidate_name: &str,
659	    cmd: &clap::Command,
660	    subcommand: &clap::Command,
661	) -> CompletionCandidate {
662	    CompletionCandidate::new(candidate_name.to_owned())
663	        .help(subcommand.get_about().cloned())
664	        .id(Some(format!("command::{candidate_name}")))
665	        .tag(Some(
666	            cmd.get_subcommand_help_heading()
667	                .unwrap_or("Commands")
668	                .to_owned()
669	                .into(),
670	        ))
671	        .display_order(Some(subcommand.get_display_order()))
672	        .hide(subcommand.is_hide_set())
673	}
674	
675	/// Parse the short flags and find the first `takes_values` option.
676	///
677	/// Returns the raw leading flags, every matched argument, the first
678	/// `takes_values` option (if any), and the remaining unparsed flags.
679	fn parse_shortflags<'c, 's>(
680	    cmd: &'c clap::Command,
681	    mut short: clap_lex::ShortFlags<'s>,
682	) -> (
683	    String,
684	    Vec<&'c clap::Arg>,
685	    Option<&'c clap::Arg>,
686	    clap_lex::ShortFlags<'s>,
687	) {
688	    let takes_value_opt;
689	    let mut matched_opts = Vec::new();
690	    let mut leading_flags = String::new();
691	    // Find the first takes_values option.
692	    loop {
693	        match short.next_flag() {
694	            Some(Ok(opt)) => {
695	                leading_flags.push(opt);
696	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
697	                if let Some(opt) = opt {
698	                    matched_opts.push(opt);
699	                }
700	                if opt
701	                    .map(|o| o.get_num_args().expect("built").takes_values())
702	                    .unwrap_or(false)
703	                {
704	                    takes_value_opt = opt;
705	                    break;
706	                }
707	            }
708	            Some(Err(_)) | None => {
709	                takes_value_opt = None;
710	                break;
711	            }
712	        }
713	    }
714	
715	    (leading_flags, matched_opts, takes_value_opt, short)
716	}
717	
718	/// Whether the argument can be addressed by the long flag `flag`,
719	/// including visible and hidden aliases.
720	fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
721	    arg.get_long() == Some(flag)
722	        || arg
723	            .get_all_aliases()
724	            .is_some_and(|aliases| aliases.contains(&flag))
725	}
726	
727	/// Whether the argument can be addressed by the short flag `flag`,
728	/// including visible and hidden aliases.
729	fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
730	    arg.get_short() == Some(flag)
731	        || arg
732	            .get_all_short_aliases()
733	            .is_some_and(|aliases| aliases.contains(&flag))
734	}
735	
736	/// Remove argument candidates that are unavailable given the arguments
737	/// already present on the command line.
738	///
739	/// Two rules apply:
740	/// - Non-multiple argument groups: once any member of such a group is on the
741	///   command line, every member of that group (including the selected one and
742	///   all of its aliases) is removed, mirroring the parser's one-of constraint.
743	/// - Explicit conflicts: a candidate that conflicts with an already-used
744	///   argument is removed; conflicts only need to be declared on one side.
745	///
746	/// Anything that is not an argument candidate (positional values,
747	/// subcommands, custom candidates) is left untouched.
748	fn filter_unavailable_args(
749	    completions: &mut Vec<CompletionCandidate>,
750	    cmd: &clap::Command,
751	    used_args: &[clap::Id],
752	) {
753	    if used_args.is_empty() {
754	        return;
755	    }
756	
757	    // Members of non-multiple groups that already have a member present.
758	    let mut excluded_by_group = std::collections::HashSet::<clap::Id>::new();
759	    for group in cmd.get_groups().filter(|group| !group.is_multiple_set()) {
760	        let members: Vec<&clap::Id> = group.get_args().collect();
761	        if members
762	            .iter()
763	            .any(|id| used_args.iter().any(|used| used == *id))
764	        {
765	            excluded_by_group.extend(members.into_iter().cloned());
766	        }
767	    }
768	
769	    completions.retain(|candidate| {
770	        let Some(arg) = candidate
771	            .get_id()
772	            .and_then(|id| id.strip_prefix("arg::"))
773	            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
774	        else {
775	            return true;
776	        };
777	        if excluded_by_group.contains(arg.get_id()) {
778	            return false;
779	        }
780	        !used_args.iter().any(|used_id| {
781	            cmd.get_arguments()
782	                .find(|a| a.get_id() == used_id)
783	                .is_some_and(|used| args_conflict(cmd, arg, used))
784	        })
785	    });
786	}
787	
788	/// Record an argument seen on the command line, keeping the first occurrence
789	/// only so that repeating a flag neither alters filtering nor restores
790	/// candidates already excluded.
791	fn record_used_arg(used_args: &mut Vec<clap::Id>, id: &clap::Id) {
792	    if !used_args.iter().any(|used| used == id) {
793	        used_args.push(id.clone());
794	    }
795	}
796	
797	/// De-duplicate flag candidates.
798	///
799	/// With an empty word every long spelling of an argument (its long name and
800	/// visible aliases) is offered, while short spellings are still collapsed to
801	/// the canonical short and dropped for arguments that also have a long form.
802	/// Once a prefix is typed at most one spelling of an argument can match, so
803	/// candidates are de-duplicated by argument id as before.
804	fn dedup_argument_candidates(completions: &mut Vec<CompletionCandidate>, empty_word: bool) {
805	    if empty_word {
806	        let long_ids: std::collections::HashSet<String> = completions
807	            .iter()
808	            .filter(|candidate| {
809	                candidate.get_id().is_some() && candidate.get_value().starts_with("--")
810	            })
811	            .filter_map(|candidate| candidate.get_id().cloned())
812	            .collect();
813	        let mut seen_short_ids = std::collections::HashSet::new();
814	        completions.retain(|candidate| {
815	            let Some(id) = candidate.get_id() else {
816	                return true;
817	            };
818	            if candidate.get_value().starts_with("--") {
819	                // Keep the long name and every visible alias.
820	                true
821	            } else if long_ids.contains(id) {
822	                // Prefer the long forms over the short ones.
823	                false
824	            } else {
825	                seen_short_ids.insert(id.clone())
826	            }
827	        });
828	    } else {
829	        let mut seen_ids = std::collections::HashSet::new();
830	        completions.retain(|candidate| {
831	            if let Some(id) = candidate.get_id().cloned() {
832	                seen_ids.insert(id)
833	            } else {
834	                true
835	            }
836	        });
837	    }
838	}
839	
840	/// Whether `first` and `second` conflict, no matter which one declares it.
841	fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
842	    cmd.get_arg_conflicts_with(first)
843	        .iter()
844	        .any(|c| c.get_id() == second.get_id())
845	        || cmd
846	            .get_arg_conflicts_with(second)
847	            .iter()
848	            .any(|c| c.get_id() == first.get_id())
849	}
850	
851	/// The positional the parser would fill at `pos_index`.
852	///
853	/// A `last(true)` positional only exists after `--`; before the terminator
854	/// the parser rejects values for it, so it must not be completed.
855	fn find_positional(cmd: &clap::Command, pos_index: usize, is_escaped: bool) -> Option<&clap::Arg> {
856	    cmd.get_positionals()
857	        .find(|p| p.get_index() == Some(pos_index) && (is_escaped || !p.is_last_set()))
858	}
859	
860	/// Parse the positional arguments. Return the new state and the new positional index.
861	fn parse_positional<'a>(
862	    cmd: &clap::Command,
863	    pos_index: usize,
864	    is_escaped: bool,
865	    state: ParseState<'a>,
866	) -> (ParseState<'a>, usize) {
867	    let pos_arg = cmd
868	        .get_positionals()
869	        .find(|p| p.get_index() == Some(pos_index));
870	    let num_args = pos_arg
871	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
872	        .unwrap_or(1);
873	
874	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
875	        if num_args > 1 {
876	            (ParseState::Pos((pos_index, 1)), pos_index)
877	        } else {
878	            if is_escaped {
879	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
880	            } else {
881	                (ParseState::ValueDone, pos_index + 1)
882	            }
883	        }
884	    };
885	    match state {
886	        ParseState::ValueDone => {
887	            update_state_with_new_positional(pos_index)
888	        },
889	        ParseState::Pos((prev_pos_index, num_arg)) => {
890	            if prev_pos_index == pos_index {
891	                if num_arg + 1 < num_args {
892	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
893	                } else {
894	                    if is_escaped {
895	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
896	                    } else {
897	                        (ParseState::ValueDone, pos_index + 1)
898	                    }
899	                }
900	            } else {
901	                update_state_with_new_positional(pos_index)
902	            }
903	        }
904	        ParseState::Opt(..) => unreachable!(
905	            "This branch won't be hit,
906	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
907	        ),
908	    }
909	}
910	
911	/// Parse optional flag argument. Return new state
912	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
913	    let range = opt.get_num_args().expect("built");
914	    let max = range.max_values();
915	    if count < max {
916	        ParseState::Opt((opt, count + 1))
917	    } else {
918	        ParseState::ValueDone
919	    }
920	}
921	
922	/// How many of an option's values an attached `=value` (or `-ovalue`) accounts
923	/// for, honoring the value delimiter.
924	fn attached_value_count(opt: &clap::Arg, value: &OsStr) -> usize {
925	    match (opt.get_value_delimiter(), value.to_str()) {
926	        (Some(delimiter), Some(value)) => value.split(delimiter).count(),
927	        _ => 1,
928	    }
929	}
930	
931	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
932	    cmd.get_positionals()
933	        .find(|a| a.get_index() == Some(pos_index))
934	        .map(|p| p.is_allow_hyphen_values_set())
935	        .unwrap_or(false)
936	}
937	
938	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
939	    let val = arg.to_value_os();
940	    if val.starts_with("-") {
941	        if let ParseState::Opt((opt, _)) = state {
942	            return opt.is_allow_hyphen_values_set();
943	        }
944	    }
945	
946	    false
947	}
948	
949	/// Whether `arg` is the standalone value terminator of a pending option.
950	///
951	/// Like the parser, an attached value (`--opt=;`) is not a terminator: the
952	/// word must consist of the terminator alone.
953	fn is_value_terminator(opt: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
954	    opt.get_value_terminator()
955	        .is_some_and(|term| arg.to_value_os() == OsStr::new(term.as_str()))
956	}
957	
958	/// Whether the parser would route this word through flag/escape parsing before
959	/// a pending option gets to consume it as a value.
960	fn is_flag_like(arg: &clap_lex::ParsedArg<'_>) -> bool {
961	    arg.is_escape() || arg.to_long().is_some() || arg.to_short().is_some()
962	}
963	
964	/// Whether a word can terminate a still-open multi-value option and start a
965	/// new argument instead, the way the parser would read it.
966	///
967	/// While an option still owes values, the parser greedily consumes every plain
968	/// word as one of its values; only flag-like words can switch to another
969	/// argument. An option that accepts hyphen values consumes those too.
970	fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
971	    if arg.is_escape() {
972	        // `--` cancels every pending option unless its values may start with `--`.
973	        return !pending.is_allow_hyphen_values_set();
974	    }
975	    if !arg.to_value_os().starts_with("-") {
976	        // A plain word is always another value of the pending option.
977	        return false;
978	    }
979	    if pending.is_allow_hyphen_values_set() {
980	        return false;
981	    }
982	    // `-` is a stdio/value, not a flag.
983	    if arg.is_stdio() {
984	        return false;
985	    }
986	    // Both long and short flag styles can start a new argument; unknown flags
987	    // still switch (and error during parsing) rather than become option values.
988	    arg.to_long().is_some() || arg.to_short().is_some()
989	}
