432	///
433	/// Using this explicitly is intended for arguments that also accept other value formats that need
434	/// to be completed and the completer is eager ([`ValueCandidates`]).
435	/// For lazy completion, see [`complete_possible_values`].
436	pub fn possible_value_candidates(
437	    values: impl IntoIterator<Item = clap::builder::PossibleValue>,
438	) -> Vec<CompletionCandidate> {
439	    values
440	        .into_iter()
441	        .map(|p| {
442	            CompletionCandidate::new(OsString::from(p.get_name()))
443	                .help(p.get_help().cloned())
444	                .hide(p.is_hide_set())
445	        })
446	        .collect()
447	}
