use clap::{Arg, ArgAction, Command};

fn cmd_set() -> Command {
    Command::new("tool")
        .disable_help_flag(true).disable_version_flag(true)
        .arg(Arg::new("tag").long("tag").num_args(1..=3).value_delimiter(',')
            .value_parser(["red", "green", "blue"]))
}
fn cmd_app() -> Command {
    Command::new("tool")
        .disable_help_flag(true).disable_version_flag(true)
        .arg(Arg::new("tag").long("tag").action(ArgAction::Append).num_args(1..=3)
            .value_delimiter(',').value_parser(["red", "green", "blue"]))
}

fn try_parse(cmd: &Command, args: &[&str]) {
    let m = cmd.try_get_matches_from(args.to_vec());
    match m {
        Ok(m) => {
            let tags: Vec<&String> = m.get_many::<String>("tag").map(|v| v.collect()).unwrap_or_default();
            println!("{args:?} => Ok tags={tags:?}");
        }
        Err(e) => println!("{args:?} => Err({:?})", e.kind()),
    }
}

fn main() {
    println!("-- Set num_args(1..=3) --");
    for a in [
        &["tool", "--tag", "red,green,blue"][..],
        &["tool", "--tag", "red,green,blue,red"],
        &["tool", "--tag", "red,green", "--tag", "blue"],
        &["tool", "--tag", "red", "--tag", "green"],
