/// State kept while the values of an option are still being parsed.
#[derive(Debug, PartialEq, Eq, Clone)]
struct OptState<'a> {
    opt: &'a clap::Arg,
    /// Shell-word values consumed, counting the way the parser does so that
    /// [`ArgValueCompleter::complete_at`] keeps indexing shell arguments.
    words: usize,
    /// Canonical possible-value names of the valid, completed delimiter
    /// fragments of the current occurrence. Empty for arguments that are not a
    /// strict delimited group.
    used: Vec<String>,
    /// Whether the last shell word ended with the value delimiter, meaning the
    /// next word keeps filling the very same group.
    open: bool,
    /// Whether a completed fragment of the current group was invalid (empty,
    /// unknown, duplicated, or past the group's capacity). Such a group stays
    /// locked on value completion and never yields candidates again.
    invalid: bool,
}

impl<'a> OptState<'a> {
    fn new(opt: &'a clap::Arg, words: usize) -> Self {
        Self {
            opt,
            words,
            used: Vec::new(),
            open: false,
            invalid: false,
        }
    }

    /// Whether this argument's values are validated as a delimited group with
    /// a capacity larger than a single fragment.
    fn is_strict_group(&self) -> bool {
        self.opt.get_value_delimiter().is_some()
            && self.opt.get_num_args().expect("built").max_values() > 1
            && possible_values(self.opt).is_some()
    }

    /// Whether the next shell word must be consumed as another value of this
    /// option no matter how it is shaped (flag, escape, subcommand name).
    ///
    /// A trailing delimiter opens a fragment that is still being typed, and an
    /// invalid completed group can never be salvaged by reinterpreting a word
    /// as a different kind of argument.
    fn locks_next_word(&self) -> bool {
        self.is_strict_group() && (self.open || self.invalid)
    }

    /// Whether the option still accepts another plain value.
    fn wants_more_values(&self) -> bool {
        if self.is_strict_group() {
            self.open || self.invalid || self.used.len() < self.capacity()
        } else {
            self.words < self.opt.get_num_args().expect("built").max_values()
        }
    }

    fn capacity(&self) -> usize {
        self.opt.get_num_args().expect("built").max_values()
    }
}

