use clap::{Arg, ArgAction, Command};
fn cmd() -> Command {
    Command::new("tool").disable_help_flag(true).disable_version_flag(true)
        .arg(Arg::new("tag").long("tag").action(ArgAction::Append).num_args(1..=3)
            .value_delimiter(',').value_parser(["red","green","blue"]))
        .arg(Arg::new("src").value_parser(["src"])).arg(Arg::new("dst").value_parser(["dst"]))
        .subcommand(Command::new("run").disable_help_flag(true).disable_version_flag(true)
            .arg(Arg::new("tag").long("tag").action(ArgAction::Append).num_args(1..=3)
                .value_delimiter(',').value_parser(["job","log","tmp"]))
            .arg(Arg::new("test").value_parser(["test"])).arg(Arg::new("bench").value_parser(["bench"])))
}
fn p(args: &[&str]) {
    match cmd().try_get_matches_from(args.to_vec()) {
        Ok(m) => { let t: Vec<&String> = m.get_many::<String>("tag").map(|i| i.collect()).unwrap_or_default();
            println!("{args:?} => Ok root_tags={t:?} sub={:?}", m.subcommand_name());
            if let Some((_,sm)) = m.subcommand() { let st: Vec<&String> = sm.get_many::<String>("tag").map(|i| i.collect()).unwrap_or_default(); println!("     run tags={st:?}"); } }
        Err(e) => println!("{args:?} => Err({:?})", e.kind()),
    }
}
fn main() {
    for a in [&["tool","--tag","red,green,blue","run"][..],
              &["tool","--tag=red,green,blue","run"],
              &["tool","--tag=red,green,blue","run","--tag=job,"],
              &["tool","run","--tag=job,"],
    ] { p(a); }
}
