/// State kept while the values of an option are still being parsed.
#[derive(Debug, PartialEq, Eq, Clone)]
struct OptState<'a> {
    opt: &'a clap::Arg,
    /// Shell-word values consumed, counted the way the parser does so that
    /// [`ArgValueCompleter::complete_at`] keeps indexing shell arguments
    /// rather than delimiter-separated fragments.
    words: usize,
    /// Canonical possible-value names of the valid, committed fragments of
    /// the current occurrence. Only populated for strict delimited groups.
    used: Vec<String>,
    /// Whether a committed fragment of the current group was invalid (empty,
    /// unknown, duplicated, or past the group's capacity). Such a group stays
    /// locked on value completion and never yields candidates or lets a later
    /// word switch scope.
    invalid: bool,
}

impl<'a> OptState<'a> {
    fn new(opt: &'a clap::Arg) -> Self {
        Self {
            opt,
            words: 0,
            used: Vec::new(),
            invalid: false,
        }
    }

    /// Whether this option's values form a delimited group that can hold more
    /// than one fragment and whose fragments are validated while typed.
    ///
    /// This deliberately excludes single-value options (max of one), whose
    /// delimiter is only used to join several suggestions into one word, and
    /// arguments without possible values to validate against.
    fn is_strict_group(&self) -> bool {
        self.opt.get_value_delimiter().is_some()
            && self.opt.get_num_args().expect("built").max_values() > 1
            && possible_values(self.opt).is_some()
    }

    /// Maximum number of fragments accepted in one occurrence.
    fn capacity(&self) -> usize {
        self.opt.get_num_args().expect("built").max_values()
    }

    /// Record a shell word (already submitted, so not the word under the
    /// cursor) as a value of this option, splitting and validating it when the
    /// option is a strict delimited group.
    fn observe(&mut self, word: &OsStr) {
        self.words += 1;
        if !self.is_strict_group() || self.invalid {
            return;
        }
        let delimiter = self.opt.get_value_delimiter().expect("strict group");
        let capacity = self.capacity();
        let Some(word) = word.to_str() else {
            self.invalid = true;
            return;
        };
        for fragment in word.split(delimiter) {
            if self.used.len() >= capacity {
                self.invalid = true;
                break;
            }
            match canonical_possible_value(self.opt, fragment) {
                Some(name) if !self.used.contains(&name) => self.used.push(name),
                _ => {
                    // Empty (also a trailing or doubled delimiter), unknown, or
                    // duplicated fragment: the parser would reject the group.
                    self.invalid = true;
                    break;
                }
            }
        }
    }

    /// The parse state after this option consumed a value.
    fn into_parse_state(self) -> ParseState<'a> {
        if self.is_strict_group() && !self.invalid && self.used.len() >= self.capacity() {
            // Every fragment slot is filled with a valid value, so the group is
            // complete and ordinary parsing resumes.
            ParseState::ValueDone
        } else if self.is_strict_group() || self.words < self.opt.get_num_args().expect("built").max_values() {
            ParseState::Opt(self)
        } else {
            ParseState::ValueDone
        }
    }
}

