use clap::{Arg, ArgAction, Command};
fn mk(cap: bool) -> Command {
    let a = if cap {
        Arg::new("tag").long("tag").action(ArgAction::Append).num_args(1..=3)
    } else {
        Arg::new("tag").long("tag").action(ArgAction::Append)
    };
    Command::new("tool").disable_help_flag(true).disable_version_flag(true)
        .arg(a.value_delimiter(',').value_parser(["red","green","blue"]))
        .arg(Arg::new("src").value_parser(["src"])).arg(Arg::new("dst").value_parser(["dst"]))
        .subcommand(Command::new("run").disable_help_flag(true).disable_version_flag(true)
            .arg(Arg::new("tag").long("tag").action(ArgAction::Append).num_args(1..=3)
                .value_delimiter(',').value_parser(["job","log","tmp"])))
}
fn p(cap: bool, args: &[&str]) {
    match mk(cap).try_get_matches_from(args.to_vec()) {
        Ok(m) => { let t: Vec<&String> = m.get_many::<String>("tag").map(|i| i.collect()).unwrap_or_default();
            println!("cap={cap} {args:?} => Ok tags={t:?} sub={:?}", m.subcommand_name()); }
        Err(e) => println!("cap={cap} {args:?} => Err({:?})", e.kind()),
    }
}
fn main() {
    for &cap in &[false,true] {
        for a in [&["tool","--tag=red","run"][..],
                  &["tool","--tag","red","run"],
                  &["tool","--tag=red,green","run"],
                  &["tool","--tag","red,green","run"],
                  &["tool","--tag=red,green,blue","run"],
                  &["tool","--tag=red","run","--tag=job,"],
        ] { p(cap,a); }
        println!();
    }
}
