    fn capacity(&self) -> usize {
        self.opt.get_num_args().expect("built").max_values()
    }

    /// Maximum number of space-separated values the option accepts.
    fn max_words(&self) -> usize {
        self.opt.get_num_args().expect("built").max_values()
    }

    /// Record a shell word as a value of this option. For strict delimited
    /// groups the word is split and every fragment except the one still being
    /// typed (the empty slot implied by a trailing delimiter) is validated.
    fn observe(&mut self, word: &OsStr) {
        self.words += 1;
