            if self.used.len() >= capacity {
                self.invalid = true;
                break;
            }
            match canonical_possible_value(self.opt, fragment) {
                Some(name) if !self.used.contains(&name) => self.used.push(name),
                _ => {
                    // Empty (also a doubled delimiter), unknown, or duplicated
                    // fragment: the parser would reject this group.
                    self.invalid = true;
                    break;
                }
            }
        }
    }

    /// Consume a value and return the state parsing should resume with.
    ///
    /// `attached` marks a value glued to the flag (`--opt=value`). Such a value
    /// closes its occurrence as soon as it is valid and complete, even when the
    /// group could still hold more fragments; a space-separated occurrence
    /// greedily keeps consuming plain words up to its capacity.
    fn finish(self, attached: bool) -> ParseState<'a> {
        if self.is_strict_group() {
            if self.invalid || self.open {
                // A locked group keeps consuming every later word as a value.
