    /// Consume a value and return the state parsing should resume with.
    ///
    /// `attached` marks the value as glued to its flag (`--opt=value`), which
    /// satisfies the occurrence on its own and never greedily consumes a later
    /// space-separated word. A space-separated occurrence instead stays pending
    /// until it reaches its capacity, the way the parser greedily fills a
    /// multi-value option.
    ///
    /// In every form, a fragment still being typed (a trailing delimiter) or an
    /// invalid committed fragment keeps the group locked on values.
    fn finish(self, attached: bool) -> ParseState<'a> {
        if self.is_strict_group() {
            if self.words == 0 || self.invalid || self.open {
                ParseState::Opt(self)
            } else if attached || self.used.len() >= self.capacity() {
                ParseState::ValueDone
            } else {
                ParseState::Opt(self)
            }
        } else if self.words >= self.max_words() {
            ParseState::ValueDone
        } else {
            ParseState::Opt(self)
        }
    }
}


/// Whether an option's values form a delimited group that can hold more than
/// one fragment and whose fragments are validated while typed.
///
/// Single-value options (a maximum of one) are excluded: their delimiter only
/// joins several suggestions into one word, so completed fragments are not
/// validated against each other.
fn is_strict_group_arg(arg: &clap::Arg) -> bool {
    arg.get_value_delimiter().is_some()
        && arg.get_num_args().expect("built").max_values() > 1
        && possible_values(arg).is_some()
}

