use clap::{Arg, ArgAction, Command};
fn cmd() -> Command {
    Command::new("tool").disable_help_flag(true).disable_version_flag(true).disable_help_subcommand(true)
        .arg(Arg::new("tag").long("tag").action(ArgAction::Append).num_args(1..=3)
            .value_delimiter(',').value_parser(["red","green","blue"]))
        .arg(Arg::new("verbose").long("verbose").action(ArgAction::SetTrue))
        .arg(Arg::new("path").value_parser(["src","dst"]))
        .subcommand(Command::new("run").disable_help_flag(true).disable_version_flag(true).disable_help_subcommand(true)
            .arg(Arg::new("tag").long("tag").action(ArgAction::Append).num_args(1..=3)
                .value_delimiter(',').value_parser(["job","log","tmp"]))
            .arg(Arg::new("run-path").value_parser(["test","bench"])))
}
fn v(args:&[&str])->Vec<String>{ let mut c=cmd(); let w:Vec<std::ffi::OsString>=args.iter().map(std::ffi::OsString::from).collect();
  match clap_complete::engine::complete(&mut c,w,args.len()-1,None){
    Ok(cs)=>cs.into_iter().map(|c|c.get_value().to_string_lossy().into_owned()).collect(),
    Err(e)=>panic!("error for {args:?}: {e}"),
  }}
fn main(){
  println!("legal space/equals: {:?} | {:?}", v(&["tool","--tag",""]), v(&["tool","--tag="]));
  println!("red,: {:?}", v(&["tool","--tag","red,"]));
  println!("red,g: {:?}", v(&["tool","--tag","red,g"]));
  println!("dup: {:?} unknown: {:?} dblcomma: {:?}", v(&["tool","--tag","red,red,"]), v(&["tool","--tag","red,x,"]), v(&["tool","--tag","red,,"]));
  println!("cap then empty: {:?}", v(&["tool","--tag","red,green,blue",""]));
  println!("cap request: {:?}", v(&["tool","--tag","red,green,blue,"]));
  println!("pending verbose/run/opt: {:?} {:?} {:?}", v(&["tool","--tag","red,","--verbose"]), v(&["tool","--tag","red,","run"]), v(&["tool","--tag","red,","--limit"]));
  println!("run-scoped: {:?}", v(&["tool","run","--tag=job,"]));
  println!("root no leak: {:?}", v(&["tool","--tag=red","run","--tag=job,"]));
  println!("terminator pending: {:?} complete: {:?}", v(&["tool","--tag","red,","--",""]), v(&["tool","--tag=red,green,blue","--",""]));
  println!("after term comma/opt/sub/unk: {:?} {:?} {:?} {:?}",
